#!/usr/bin/env python3
"""
Project Generator: FX Fix-Aware Market Making Platform
Recreates the entire project source tree from scratch.

Implements Krohn, Mueller & Whelan (Journal of Finance, 2024):
W-shaped FX fix pattern for systematic market making on CME FX futures.

Data sources:
  - Yahoo Finance: real intraday FX data (1h bars, 2 years)
  - FRED API: OIS rates, Treasury yields, FX spot rates
  - Databento: CME Globex MBP-10 order book (6E, 6B, 6J, 6A)
  - Synthetic: RFQ flow only (proprietary bank data)

Usage:
    python generate_project.py
    python generate_project.py --target-dir /path/to/new/project
"""
import argparse
import base64
import json
import zlib
from pathlib import Path

_DATA = """"""


def main():
    ap = argparse.ArgumentParser(description='Generate FX project source tree')
    ap.add_argument('--target-dir', default='.', help='Target directory')
    args = ap.parse_args()

    target = Path(args.target_dir)
    target.mkdir(parents=True, exist_ok=True)

    raw = zlib.decompress(base64.b64decode(_DATA))
    files = json.loads(raw.decode('utf-8'))

    n = len(files)
    print('Generating ' + str(n) + ' files in ' + str(target.resolve()))
    print()

    for rel_path, content in files.items():
        fp = target / rel_path
        fp.parent.mkdir(parents=True, exist_ok=True)
        fp.write_text(content, encoding='utf-8')
        print('  wrote ' + rel_path)

    for d in ['data', 'data/databento_cache', 'data/yfinance_cache', 'data/cache', 'output']:
        (target / d).mkdir(parents=True, exist_ok=True)

    print()
    print(str(n) + ' files generated.')
    print()
    print('Next steps:')
    print('  1. pip install -r requirements.txt')
    print('  2. cp .env.example .env  # then add your API keys')
    print('  3. cd shared/cpp_kernel && python setup.py build_ext --inplace')
    print('  4. python run_full_demo.py')


if __name__ == '__main__':
    main()
